Let me create these files.

For `server.py`:
- Use `http.server` and `threading` (or `socketserver`).
- Track rate limits per client IP with a dict of timestamps.
- On each request to /api/time: check if the client IP has made fewer than 5 requests in the last 60 seconds. If so, record the timestamp and return 200. Otherwise, return 429 with Retry-After header.

Note: "The 6th and further requests within the window return 429" — so requests 1–5 are allowed, and requests 6+ are 429. So the limit is 5 per window.

Implementation:

```python
import time
import json
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlparse

RATE_LIMIT = 5
WINDOW_SECONDS = 60

# client_ip -> list of timestamps
_rate_limits = {}

class Handler(BaseHTTPRequestHandler):
    def do_GET(self):
        path = urlparse(self.path).path
        if path == "/api/time":
            self.handle_time()
        else:
            self.send_error(404)

    def handle_time(self):
        client_ip = self.client_address[0]
        now = time.time()
        timestamps = _rate_limits.setdefault(client_ip, [])
        # filter out timestamps outside the window
        recent = [t for t in timestamps if now - t < WINDOW_SECONDS]
        if len(recent) >= RATE_LIMIT:
            self.send_response(429)
            self.send_header("Retry-After", str(int(WINDOW_SECONDS)))
            self.end_headers()
            return
        recent.append(now)
        _rate_limits[client_ip] = recent
        body = json.dumps({"now": int(now)}).encode()
        self.send_response(200)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def log_message(self, format, *args):
        pass  # keep output clean

def main():
    server = ThreadingHTTPServer(("0.0.0.0", 8000), Handler)
    print("Server running on port 8000")
    server.serve_forever()

if __name__ == "__main__":
    main()
```

