class Handler(BaseHTTPRequestHandler):
    def do_GET(self):
        path = urlparse(self.path).path
        if path == "/api/time":
            self.handle_time()
        else:
            self.send_error(404)

    def handle_time(self):
        client_ip = self.client_address[0]
        now = time.time()
        timestamps = _rate_limits.setdefault(client_ip, [])
